import garb from './assets/garb.svg';
// TaskList takes tasks and displays them
const TaskList = ({tasks, deleteTask}) => {

    return (
      <div className="taskDisplayContainer w-full space-y-4 max-h-[400px] overflow-y-auto">
        {tasks.map((task, index) => (
          <div
            className="taskDisplay relative py-2 flex flex-col items-center justify-center w-full font-normal border-b border-white last:border-none"
            key={task.id}
          >
            <button
              className="ml-auto rounded-lg cursor-pointer bg-white bg-opacity-20 hover:bg-opacity-5 hover:scale-105 transition duration-100 ease-in-out"
              onClick={() => deleteTask(task.id)}
            >
              <img id="garb" src={garb} alt="delete task" />
            </button>
            <h1 className="whitespace-normal break-words w-4/ text-white text-3xl sm:text-2xl font-normal my-2 p-0">
              {task.name}
            </h1>
            {task.desc && (
              <p className="whitespace-normal break-words w-4/5 text-white sm:text-lg font-normal my-2 p-0">
                {task.desc}
              </p>
            )}
          </div>
        ))}
      </div>
    );
};

export default TaskList;
